mapper.select:
select trade_date as tradeDate, rule_version as ruleVersion, source as source, picked as picked, rank_no as rankNo, close_pct as closePct, next_change_pct as nextChangePct, next_max_gain_pct as nextMaxGainPct, next_max_drawdown_pct as nextMaxDrawdownPct from stock_tail_recommend_record where eval_status = 'DONE'
and picked = #{picked}
order by trade_date desc, rank_no asc limit #{limit}
